Here is the root cause:
The bug is a lock ordering inversion between folio_lock and i_mmap_rwsem in the hugetlb migration code. In `unmap_and_move_huge_page()`, `folio_lock` is acquired before calling `try_to_migrate()` and then `remove_migration_ptes()`, which tries to acquire `i_mmap_rwsem` in read mode. Meanwhile, another code path (e.g., `hugetlbfs_fallocate()`) holds `i_mmap_rwsem` in write mode and then tries to acquire `folio_lock`. This creates a classic deadlock (ABBA). The patch fixes it by extending the scope of the already‑held `i_mmap_rwsem` write lock (from `try_to_migrate()`) to also cover `remove_migration_ptes()`, thus preventing the inversion.

Here is the patch:
  */
 static int unmap_and_move_huge_page(new_folio_t get_new_folio,
 		free_folio_t put_new_folio, unsigned long private,
 		struct folio *src, int force, enum migrate_mode mode,
 		int reason, struct list_head *ret)
 {
 	struct folio *dst;
 	int rc = -EAGAIN;
 	int page_was_mapped = 0;
 	struct anon_vma *anon_vma = NULL;
 	struct address_space *mapping = NULL;
+	enum ttu_flags ttu = 0;

 	if (folio_ref_count(src) == 1) {
 		/* page was freed from under us. So we are done. */
 		folio_putback_hugetlb(src);
 		return 0;
 	}

 	dst = get_new_folio(src, private);
 	if (!dst)
 		return -ENOMEM;

 	if (!folio_trylock(src)) {
 		if (!force)
 			goto out;
 		switch (mode) {
 		case MIGRATE_SYNC:
 			break;
 		default:
 			goto out;
 		}
 		folio_lock(src);
 	}

 	/*
 	 * Check for pages which are in the process of being freed.  Without
 	 * folio_mapping() set, hugetlbfs specific move page routine will not
 	 * be called and we could leak usage counts for subpools.
 	 */
 	if (hugetlb_folio_subpool(src) && !folio_mapping(src)) {
 		rc = -EBUSY;
 		goto out_unlock;
 	}

 	if (folio_test_anon(src))
 		anon_vma = folio_get_anon_vma(src);

 	if (unlikely(!folio_trylock(dst)))
 		goto put_anon;

 	if (folio_mapped(src)) {
-		enum ttu_flags ttu = 0;
-
 		if (!folio_test_anon(src)) {
 			/*
 			 * In shared mappings, try_to_unmap could potentially
 			 * call huge_pmd_unshare.  Because of this, take
 			 * semaphore in write mode here and set TTU_RMAP_LOCKED
 			 * to let lower levels know we have taken the lock.
 			 */
 			mapping = hugetlb_folio_mapping_lock_write(src);
 			if (unlikely(!mapping))
 				goto unlock_put_anon;

 			ttu = TTU_RMAP_LOCKED;
 		}

 		try_to_migrate(src, ttu);
 		page_was_mapped = 1;
-
-		if (ttu & TTU_RMAP_LOCKED)
-			i_mmap_unlock_write(mapping);
 	}

 	if (!folio_mapped(src))
 		rc = move_to_new_folio(dst, src, mode);

 	if (page_was_mapped)
-		remove_migration_ptes(src, !rc ? dst : src, 0);
+		remove_migration_ptes(src, !rc ? dst : src,
+				ttu ? RMP_LOCKED : 0);
+
+	if (ttu & TTU_RMAP_LOCKED)
+		i_mmap_unlock_write(mapping);

 unlock_put_anon:
 	folio_unlock(dst);

 put_anon:
 	if (anon_vma)
 		put_anon_vma(anon_vma);

 	if (!rc) {
 		move_hugetlb_state(src, dst, reason);
 		put_new_folio = NULL;
 	}

 out_unlock:
 	folio_unlock(src);
 out:
 	if (!rc)
 		folio_putback_hugetlb(src);
 	else if (rc != -EAGAIN)
 		list_move_tail(&src->lru, ret);

 	/*
 	 * If migration was not successful and there's a freeing callback,
 	 * return the folio to that special allocator. Otherwise, simply drop
 	 * our additional reference.
 	 */
 	if (put_new_folio)
 		put_new_folio(dst, private);
 	else
 		folio_put(dst);

 	return rc;
 }



